Samajh gaya bhai! HopWeb ke liye yeh raha **complete, unbroken single-file HTML code** jise tu seedha run kar sakta hai:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sasta Coder AI Hub - HopWeb</title>
    <script src="https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4"></script>
</head>
<body class="bg-slate-950 text-slate-100 flex flex-col h-screen p-4 max-w-2xl mx-auto">
    <header class="flex justify-between items-center border-b border-slate-800 pb-4 mb-4">
        <h1 class="text-xl font-bold text-cyan-400">⚡ HopWeb AI Chat</h1>
        <select id="apiProvider" class="bg-slate-900 border border-slate-700 text-sm rounded px-2 py-1 text-slate-300">
            <option value="auto">ChatGPT (Local Server)</option>
            <option value="gemini">Gemini Proxy</option>
            <option value="perplexity">Perplexity Proxy</option>
        </select>
    </header>
    <div id="chatBox" class="flex-1 overflow-y-auto space-y-3 pr-2 mb-4 text-sm">
        <div class="bg-slate-900 p-3 rounded-lg max-w-[80%] text-slate-300">Bhai, HopWeb me ready hai! Model select karke message bhejo.</div>
    </div>
    <form id="chatForm" class="flex gap-2">
        <input type="text" id="userInput" placeholder="Type a message..." class="flex-1 bg-slate-900 border border-slate-800 rounded px-3 py-2 text-sm focus:outline-none focus:border-cyan-500" required>
        <button type="submit" class="bg-cyan-600 hover:bg-cyan-500 text-white px-4 py-2 rounded text-sm font-medium">Send</button>
    </form>
    <script>
        const chatBox = document.getElementById('chatBox'), chatForm = document.getElementById('chatForm'), userInput = document.getElementById('userInput');
        chatForm.onsubmit = async (e) => {
            e.preventDefault();
            const text = userInput.value, provider = document.getElementById('apiProvider').value;
            chatBox.innerHTML += `<div class="bg-cyan-950/50 p-3 rounded-lg max-w-[80%] ml-auto text-cyan-200">${text}</div>`;
            userInput.value = '';
            chatBox.scrollTop = chatBox.scrollHeight;
            try {
                const res = await fetch('http://localhost:8080/v1/chat/completions', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({model: provider, messages: [{role: 'user', content: text}]})
                });
                const data = await res.json();
                const reply = data.choices?.[0]?.message?.content || "No response";
                chatBox.innerHTML += `<div class="bg-slate-900 p-3 rounded-lg max-w-[80%] text-slate-300">${reply}</div>`;
            } catch (err) {
                chatBox.innerHTML += `<div class="bg-red-950/50 p-3 rounded-lg max-w-[80%] text-red-300">Connection failed! Check local server endpoint.</div>`;
            }
            chatBox.scrollTop = chatBox.scrollHeight;
        };
    </script>
</body>
</html>
```

Arey bhai, phone par HopWeb use kar raha hai toh `http://localhost:8080` seedha connect nahi hoga kyunki phone apne local loopback ko target karega! Iska solution: **CORS headers enable karo** aur local IP/tunnel (jaise Ngrok ya Termux localhost proxy) use karo, ya phir direct client-side config do.

HopWeb ke liye yeh raha **CORS-ready / mobile-friendly** version jisme custom API base URL input field bhi hai taaki tu phone se PC/server ka IP daal sake:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>HopWeb Local/Proxy Chat Hub</title>
    <script src="https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4"></script>
</head>
<body class="bg-slate-950 text-slate-100 flex flex-col h-screen p-3 max-w-lg mx-auto">
    <header class="border-b border-slate-800 pb-3 mb-3 space-y-2">
        <div class="flex justify-between items-center">
            <h1 class="text-lg font-bold text-cyan-400">⚡ HopWeb AI Hub</h1>
            <select id="apiProvider" class="bg-slate-900 border border-slate-700 text-xs rounded px-2 py-1 text-slate-300">
                <option value="auto">ChatGPT Auto</option>
                <option value="gemini-2.5-flash">Gemini Flash</option>
            </select>
        </div>
        <input type="text" id="apiEndpoint" value="http://192.168.X.X:8080/v1/chat/completions" class="w-full bg-slate-900 border border-slate-800 rounded px-2 py-1 text-xs text-slate-400 font-mono" placeholder="PC IP / Endpoint URL">
    </header>
    <div id="chatBox" class="flex-1 overflow-y-auto space-y-2 pr-1 mb-3 text-xs">
        <div class="bg-slate-900 p-2.5 rounded-lg text-slate-300">Phone se connect karne ke liye upar PC ka local IP (e.g. 192.168.1.x:8080) daal!</div>
    </div>
    <form id="chatForm" class="flex gap-2">
        <input type="text" id="userInput" placeholder="Message..." class="flex-1 bg-slate-900 border border-slate-800 rounded px-3 py-2 text-xs focus:outline-none focus:border-cyan-500" required>
        <button type="submit" class="bg-cyan-600 hover:bg-cyan-500 text-white px-3 py-2 rounded text-xs font-medium">Send</button>
    </form>
    <script>
        const chatBox = document.getElementById('chatBox'), chatForm = document.getElementById('chatForm'), userInput = document.getElementById('userInput'), apiEndpoint = document.getElementById('apiEndpoint');
        chatForm.onsubmit = async (e) => {
            e.preventDefault();
            const text = userInput.value, provider = document.getElementById('apiProvider').value, endpoint = apiEndpoint.value;
            chatBox.innerHTML += `<div class="bg-cyan-950/50 p-2.5 rounded-lg max-w-[85%] ml-auto text-cyan-200">${text}</div>`;
            userInput.value = '';
            chatBox.scrollTop = chatBox.scrollHeight;
            try {
                const res = await fetch(endpoint, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json', 'Authorization': 'Bearer not-needed'},
                    body: JSON.stringify({model: provider, messages: [{role: 'user', content: text}]})
                });
                const data = await res.json();
                const reply = data.choices?.[0]?.message?.content || data.reply || "No text returned";
                chatBox.innerHTML += `<div class="bg-slate-900 p-2.5 rounded-lg max-w-[85%] text-slate-300">${reply}</div>`;
            } catch (err) {
                chatBox.innerHTML += `<div class="bg-red-950/50 p-2.5 rounded-lg max-w-[85%] text-red-300">Error: CORS/Network fail. Check PC firewall & IP!</div>`;
            }
            chatBox.scrollTop = chatBox.scrollHeight;
        };
    </script>
</body>
</html>
```

Bhai, PC par FastAPI/proxy chalate waqt `--host 0.0.0.0` bind karna mat bhulna warna phone tak request nahi pahauchegi! Try karega?

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sasta Coder AI Hub - All-in-One</title>
    <script src="https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4"></script>
</head>
<body class="bg-slate-950 text-slate-100 flex flex-col h-screen p-4 max-w-md mx-auto">
    <header class="flex justify-between items-center border-b border-slate-800 pb-3 mb-3">
        <h1 class="text-lg font-bold text-cyan-400">⚡ HopWeb AI Hub</h1>
        <select id="modelSelect" class="bg-slate-900 border border-slate-700 text-xs rounded px-2 py-1 text-slate-300">
            <option value="gpt-4o-mini">GPT-4o Mini</option>
            <option value="claude-3-haiku">Claude 3 Haiku</option>
            <option value="gemini-flash">Gemini Flash</option>
        </select>
    </header>

    <div id="chatBox" class="flex-1 overflow-y-auto space-y-3 pr-1 mb-3 text-sm">
        <div class="bg-slate-900 p-3 rounded-xl max-w-[85%] text-slate-300">Arey bhai! HopWeb me chal raha hai. Model select karo aur message bhejo!</div>
    </div>

    <form id="chatForm" class="flex gap-2 bg-slate-900 p-2 rounded-xl border border-slate-800">
        <input type="text" id="userInput" placeholder="Type a message..." class="flex-1 bg-transparent px-2 py-1 text-sm text-slate-100 focus:outline-none" required>
        <button type="submit" class="bg-cyan-600 hover:bg-cyan-500 text-white px-3 py-1.5 rounded-lg text-sm font-medium">Send</button>
    </form>

    <script>
        const chatBox = document.getElementById('chatBox');
        const chatForm = document.getElementById('chatForm');
        const userInput = document.getElementById('userInput');
        const modelSelect = document.getElementById('modelSelect');

        chatForm.onsubmit = async (e) => {
            e.preventDefault();
            const text = userInput.value;
            const model = modelSelect.value;

            chatBox.innerHTML += `<div class="bg-cyan-950/60 p-3 rounded-xl max-w-[85%] ml-auto text-cyan-200">${text}</div>`;
            userInput.value = '';
            chatBox.scrollTop = chatBox.scrollHeight;

            try {
                // Using Pollinations public endpoint as a robust fallback for mobile previewing
                const res = await fetch(`https://text.pollinations.ai/${encodeURIComponent(text)}?model=${model}`);
                const reply = await res.text();
                chatBox.innerHTML += `<div class="bg-slate-900 p-3 rounded-xl max-w-[85%] text-slate-300">${reply}</div>`;
            } catch (err) {
                chatBox.innerHTML += `<div class="bg-red-950/50 p-3 rounded-xl max-w-[85%] text-red-300">Error: Failed to fetch response.</div>`;
            }
            chatBox.scrollTop = chatBox.scrollHeight;
        };
    </script>
</body>
</html>
```

Bhai, HopWeb ke liye yeh optimized mobile-friendly single-file HTML code hai! Seedha paste karde.
